fn buildGrid(n: Int) -> Int[] {
    let grid: Int[] = [];
    loop i in 0..(n * n) {
        grid = grid + [0];
    }
    ret grid;
}

fn main() -> Void {
    let n: Int = 4;
    let grid: Int[] = buildGrid(n);
    let top: Int = 0;
    let bottom: Int = n - 1;
    let left: Int = 0;
    let right: Int = n - 1;
    let v: Int = 1;
    loop top <= bottom && left <= right {
        loop c in left..(right + 1) {
            grid[top * n + c] = v;
            v = v + 1;
        }
        top = top + 1;
        loop r in top..(bottom + 1) {
            grid[r * n + right] = v;
            v = v + 1;
        }
        right = right - 1;
        if top <= bottom {
            let c2: Int = right;
            loop c2 >= left {
                grid[bottom * n + c2] = v;
                v = v + 1;
                c2 = c2 - 1;
            }
            bottom = bottom - 1;
        }
        if left <= right {
            let r2: Int = bottom;
            loop r2 >= top {
                grid[r2 * n + left] = v;
                v = v + 1;
                r2 = r2 - 1;
            }
            left = left + 1;
        }
    }
    fx {
        loop r in 0..n {
            let line: Text = "";
            loop c in 0..n {
                line = line + int_to_text(grid[r * n + c]);
                if c < n - 1 { line = line + " "; }
            }
            println("row ", r, ": ", line);
        }
        println("total = ", v - 1);
    }
    ret;
}

type Parser {
    src: Text;
    pos: Int = 0;

    fn peek() -> Text {
        if self.pos >= string_len(self.src) { ret ""; }
        ret self.src[self.pos];
    }

    fn bump() -> Void {
        self.pos = self.pos + 1;
        ret;
    }

    fn parseNumber() -> Int {
        let n: Int = 0;
        loop true {
            let c: Text = self.peek();
            if c == "" { break; }
            if c < "0" || c > "9" { break; }
            n = n * 10 + (ord(c) - ord("0"));
            self.bump();
        }
        ret n;
    }

    fn parseFactor() -> Int {
        if self.peek() == "(" {
            self.bump();
            let v: Int = self.parseExpr();
            if self.peek() == ")" { self.bump(); }
            ret v;
        }
        ret self.parseNumber();
    }

    fn parseTerm() -> Int {
        let v: Int = self.parseFactor();
        loop true {
            let c: Text = self.peek();
            if c == "*" {
                self.bump();
                v = v * self.parseFactor();
            } else {
                if c == "/" {
                    self.bump();
                    let d: Int = self.parseFactor();
                    if d != 0 { v = v / d; }
                } else {
                    break;
                }
            }
        }
        ret v;
    }

    fn parseExpr() -> Int {
        let v: Int = self.parseTerm();
        loop true {
            let c: Text = self.peek();
            if c == "+" {
                self.bump();
                v = v + self.parseTerm();
            } else {
                if c == "-" {
                    self.bump();
                    v = v - self.parseTerm();
                } else {
                    break;
                }
            }
        }
        ret v;
    }
}

fn evalExpr(s: Text) -> Int {
    let p: Parser = new Parser { src: s, pos: 0 };
    ret p.parseExpr();
}

fn main() -> Void {
    let exprs: Text[] = ["2+3*4", "(2+3)*4", "100/5-7", "2*(3+4)-(10-4)"];
    fx {
        loop i in 0..length(exprs) {
            println("expr ", i, ": ", exprs[i], " = ", evalExpr(exprs[i]));
        }
    }
    ret;
}

type Item {
    name: Text;
    category: Text;
    qty: Int;
    unitPrice: Real;

    fn value() -> Real {
        ret self.qty * self.unitPrice;
    }
}

fn main() -> Void {
    let names: Text[] = ["bolt", "nut", "hammer", "wrench", "screw", "saw"];
    let cats: Text[] = ["fastener", "fastener", "tool", "tool", "fastener", "tool"];
    let qtys: Int[] = [100, 250, 4, 7, 500, 2];
    let prices: Real[] = [0.25, 0.1, 12.5, 9.75, 0.05, 22.0];

    let catNames: Text[] = [];
    let catTotals: Real[] = [];
    let catCounts: Int[] = [];

    loop i in 0..length(names) {
        let it: Item = new Item { name: names[i], category: cats[i], qty: qtys[i], unitPrice: prices[i] };
        let idx: Int = -1;
        loop j in 0..length(catNames) {
            if catNames[j] == it.category { idx = j; }
        }
        if idx < 0 {
            catNames = catNames + [it.category];
            catTotals = catTotals + [it.value()];
            catCounts = catCounts + [1];
        } else {
            catTotals[idx] = catTotals[idx] + it.value();
            catCounts[idx] = catCounts[idx] + 1;
        }
    }

    let grand: Real = 0.0;
    fx {
        loop k in 0..length(catNames) {
            println("category ", catNames[k], ": items=", catCounts[k], " value=", formatfloat(catTotals[k], 2));
            grand = grand + catTotals[k];
        }
        println("grand total = ", formatfloat(grand, 2));
        println("categories = ", length(catNames));
    }
    ret;
}

@pure
fn encode(s: Text) -> Text {
    let out: Text = "";
    let n: Int = string_len(s);
    if n == 0 { ret out; }
    let cur: Text = s[0];
    let run: Int = 1;
    loop i in 1..n {
        let c: Text = s[i];
        if c == cur {
            run = run + 1;
        } else {
            out = out + cur;
            out = out + int_to_text(run);
            cur = c;
            run = 1;
        }
    }
    out = out + cur;
    out = out + int_to_text(run);
    ret out;
}

@pure
fn decode(s: Text) -> Text {
    let out: Text = "";
    let n: Int = string_len(s);
    let i: Int = 0;
    loop i < n {
        let ch: Text = s[i];
        i = i + 1;
        let count: Int = 0;
        loop i < n {
            let d: Text = s[i];
            if d < "0" || d > "9" { break; }
            count = count * 10 + (ord(d) - ord("0"));
            i = i + 1;
        }
        loop k in 0..count {
            out = out + ch;
        }
    }
    ret out;
}

fn main() -> Void {
    let cases: Text[] = ["aaabbbcccd", "wwwwwwwwwwww", "abc", "zzzzzzzzzzzzzzzzzzzzzz"];
    fx {
        loop i in 0..length(cases) {
            let enc: Text = encode(cases[i]);
            let dec: Text = decode(enc);
            println("case ", i, ": ", cases[i]);
            println("  encoded = ", enc);
            println("  roundtrip_ok = ", dec == cases[i]);
        }
    }
    ret;
}

fn siftUp(heap: Int[], start: Int) -> Int[] {
    let h: Int[] = heap;
    let i: Int = start;
    loop i > 0 {
        let parent: Int = (i - 1) / 2;
        if h[parent] <= h[i] { break; }
        let tmp: Int = h[parent];
        h[parent] = h[i];
        h[i] = tmp;
        i = parent;
    }
    ret h;
}

fn siftDown(heap: Int[], size: Int) -> Int[] {
    let h: Int[] = heap;
    let i: Int = 0;
    loop true {
        let l: Int = 2 * i + 1;
        let r: Int = 2 * i + 2;
        let small: Int = i;
        if l < size && h[l] < h[small] { small = l; }
        if r < size && h[r] < h[small] { small = r; }
        if small == i { break; }
        let tmp: Int = h[small];
        h[small] = h[i];
        h[i] = tmp;
        i = small;
    }
    ret h;
}

fn main() -> Void {
    let input: Int[] = [42, 7, 19, 3, 88, 15, 4, 61, 23, 8];
    let heap: Int[] = [];
    loop i in 0..length(input) {
        heap = heap + [input[i]];
        heap = siftUp(heap, length(heap) - 1);
    }

    let sorted: Int[] = [];
    let size: Int = length(heap);
    loop size > 0 {
        sorted = sorted + [heap[0]];
        heap[0] = heap[size - 1];
        size = size - 1;
        heap = siftDown(heap, size);
    }

    fx {
        let line: Text = "";
        loop i in 0..length(sorted) {
            line = line + int_to_text(sorted[i]);
            if i < length(sorted) - 1 { line = line + " "; }
        }
        println("sorted = ", line);
        println("min = ", sorted[0]);
        println("max = ", sorted[length(sorted) - 1]);
        let ok: Bool = true;
        loop i in 1..length(sorted) {
            if sorted[i - 1] > sorted[i] { ok = false; }
        }
        println("ordered = ", ok);
    }
    ret;
}
